class Solution {
public:
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head;

        int len = 0;
        ListNode* cur = head;
        while (cur) { len++; cur = cur->next; }

        ListNode dummy(0);
        dummy.next = head;

        for (int size = 1; size < len; size *= 2) {
            ListNode* tail = &dummy;
            cur = dummy.next;
            while (cur) {
                ListNode* left = cur;
                ListNode* right = split(left, size);
                cur = split(right, size);
                ListNode* merged = merge(left, right);
                tail->next = merged;
                while (tail->next) tail = tail->next;
            }
        }
        return dummy.next;
    }

private:
    ListNode* split(ListNode* head, int size) {
        if (!head) return nullptr;
        while (size > 1 && head->next) {
            head = head->next;
            size--;
        }
        ListNode* rest = head->next;
        head->next = nullptr;
        return rest;
    }

    ListNode* merge(ListNode* l1, ListNode* l2) {
        ListNode dummy(0);
        ListNode* tail = &dummy;
        while (l1 && l2) {
            if (l1->val <= l2->val) {
                tail->next = l1;
                l1 = l1->next;
            } else {
                tail->next = l2;
                l2 = l2->next;
            }
            tail = tail->next;
        }
        tail->next = l1 ? l1 : l2;
        return dummy.next;
    }
};
